import React, { useCallback, useEffect, useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import Loader from "../../../loader/Loader";
import AddGoodsReceipt from "./AddGoodsReceipt";
import axios from "axios";
import { domain } from "../../../../security";
import Pagination from "../../Pagination";

const AllGoodsReceipts = () => {
  const [goodsReceipts, setGoodsReceipts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [expandedGR, setExpandedGR] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(5);

  const fetchData = useCallback(async () => {
    setLoading(true);
    const apiUrl = `${domain}/api/GoodsReceipts`;
    try {
      const response = await axios.get(apiUrl);
      // Sort by receipt date (newest first)
      const sortedData = response.data.sort(
        (a, b) => new Date(b.receiptDate) - new Date(a.receiptDate)
      );
      setGoodsReceipts(sortedData);
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("Failed to fetch goods receipts.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Filter and paginate data
  const filteredGRs = goodsReceipts.filter(
    (gr) =>
      gr.receiptNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      gr.receivedBy.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (gr.poNumber || "").toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Get current items for pagination
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentGRs = filteredGRs.slice(indexOfFirstItem, indexOfLastItem);

  const deleteGoodsReceipt = async (id) => {
    if (
      !window.confirm("Are you sure you want to delete this goods receipt?")
    ) {
      return;
    }
    try {
      await axios.delete(`${domain}/api/GoodsReceipts/${id}`);
      toast.success("Goods Receipt Deleted!");
      if (expandedGR === id) {
        setExpandedGR(null);
      }
      fetchData();
    } catch (error) {
      console.error("Error deleting goods receipt:", error);
      toast.error("Failed to delete goods receipt.");
    }
  };

  const openModal = () => setIsModalVisible(true);
  const closeModal = () => setIsModalVisible(false);
  const toggleExpandGR = (grId) =>
    setExpandedGR(expandedGR === grId ? null : grId);

  const getStatusColor = (status) => {
    switch (status) {
      case "Completed":
        return "bg-green-100 text-green-800 border-green-200";
      case "Partial":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      case "Draft":
        return "bg-gray-100 text-gray-800 border-gray-200";
      default:
        return "bg-gray-100 text-gray-800 border-gray-200";
    }
  };

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  return (
    <div className="min-h-screen py-6">
      <div className="max-w-6xl mx-auto px-4">
        <ToastContainer position="top-right" autoClose={3000} />

        {/* Header */}
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Goods Receipts</h1>
            <p className="text-gray-600 text-sm">
              {filteredGRs.length} receipt(s) found
            </p>
          </div>
          <button
            onClick={openModal}
            className="bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium py-2 px-4 rounded-lg transition"
          >
            + New Goods Receipt
          </button>
        </div>

        {/* Search */}
        <div className="mb-6">
          <input
            type="text"
            placeholder="Search receipt number, receiver, or PO..."
            className="w-full p-3 border border-gray-300 rounded-lg text-sm"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setCurrentPage(1);
            }}
          />
        </div>

        {/* Modal */}
        {isModalVisible && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-4xl max-h-[90vh] overflow-hidden">
              <AddGoodsReceipt onClose={closeModal} refreshData={fetchData} />
            </div>
          </div>
        )}

        {/* Goods Receipts List */}
        {loading ? (
          <div className="flex justify-center items-center h-32">
            <Loader />
          </div>
        ) : (
          <>
            <div className="space-y-3 mb-6">
              {currentGRs.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  No goods receipts found
                </div>
              ) : (
                currentGRs.map((gr) => (
                  <div
                    key={gr.id}
                    className="bg-white rounded-lg border border-gray-200 overflow-hidden"
                  >
                    {/* Clickable Header */}
                    <div
                      className="p-4 hover:bg-gray-50 cursor-pointer transition"
                      onClick={() => toggleExpandGR(gr.id)}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-4">
                          <div
                            className={`transform transition-transform ${
                              expandedGR === gr.id ? "rotate-90" : ""
                            }`}
                          >
                            <span className="text-gray-400">▶</span>
                          </div>
                          <div className="bg-green-50 p-2 rounded">
                            <span className="text-green-600 text-sm font-medium">
                              📦
                            </span>
                          </div>
                          <div>
                            <h3 className="font-semibold text-gray-900">
                              {gr.receiptNumber}
                            </h3>
                            <p className="text-sm text-gray-600">
                              PO: {gr.poNumber || "N/A"}
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center space-x-3">
                          <span className="text-sm text-gray-600">
                            {new Date(gr.receiptDate).toLocaleDateString()}
                          </span>
                          <span
                            className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(
                              gr.status || "Completed"
                            )}`}
                          >
                            {gr.status || "Completed"}
                          </span>
                        </div>
                      </div>

                      {/* Secondary Info - UPDATED LAYOUT */}
                      <div className="flex items-start justify-between text-sm text-gray-600 mt-2 pl-12">
                        <div>
                          {/* Line 1: Items Received and Received By */}
                          <div className="flex items-center space-x-4">
                            <span>{gr.lines?.length || 0} items received</span>
                            {gr.receivedBy && (
                              <span>• Received by: {gr.receivedBy}</span>
                            )}
                          </div>

                          {/* Line 2: Notes */}
                          {gr.notes && (
                            <div className="mt-1">
                              <span className="block max-w-md truncate">
                                Notes: {gr.notes}
                              </span>
                            </div>
                          )}
                        </div>

                        {/* <div className="flex space-x-2">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              deleteGoodsReceipt(gr.id);
                            }}
                            className="text-red-600 hover:text-red-800 text-sm font-medium px-2 py-1 rounded hover:bg-red-50"
                          >
                            Delete
                          </button>
                        </div> */}
                      </div>
                    </div>

                    {/* Expandable Receipt Lines */}
                    {expandedGR === gr.id && (
                      <div className="border-t border-gray-200 bg-gray-50 p-4">
                        <h4 className="font-semibold text-gray-900 mb-3 text-sm">
                          Received Items ({gr.lines?.length || 0})
                        </h4>
                        <div className="space-y-3">
                          {gr.lines?.map((line) => (
                            <div
                              key={line.id}
                              className="bg-white rounded border p-4 text-sm"
                            >
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-3">
                                <div>
                                  <p className="font-medium text-gray-900">
                                    Product: {line.pricelist?.product || "N/A"}
                                  </p>
                                  <p className="text-gray-600 text-xs mt-1">
                                    PO Line: {line.purchaseOrderLineItemId} •
                                    Product ID:{" "}
                                    {line.pricelist?.productId || "N/A"}
                                  </p>
                                </div>
                                <div className="text-right">
                                  <p className="font-semibold text-gray-900">
                                    Quantity: {line.quantityReceived}
                                  </p>
                                </div>
                              </div>

                              {line.receiptSerialNumbers &&
                                line.receiptSerialNumbers.length > 0 && (
                                  <div className="border-t pt-3">
                                    <p className="font-medium text-gray-700 text-xs mb-2">
                                      Serial Numbers:
                                    </p>
                                    <div className="flex flex-wrap gap-2">
                                      {line.receiptSerialNumbers.map(
                                        (serial, idx) => (
                                          <span
                                            key={idx}
                                            className="bg-blue-50 text-blue-700 px-2 py-1 rounded text-xs"
                                          >
                                            {serial}
                                          </span>
                                        )
                                      )}
                                    </div>
                                  </div>
                                )}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            {/* Pagination */}
            {filteredGRs.length > itemsPerPage && (
              <Pagination
                itemsPerPage={itemsPerPage}
                totalItems={filteredGRs.length}
                currentPage={currentPage}
                paginate={paginate}
              />
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default AllGoodsReceipts;
