// File: AllUomConversions.js

import React, { useCallback, useEffect, useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import Loader from "../../../loader/Loader";
import AddUomConversion from "./AddUomConversion";
import axios from "axios";
import { domain } from "../../../../security";

const AllUomConversions = () => {
  const [conversionData, setConversionData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [conversionToEdit, setConversionToEdit] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);
  const [searchTerm, setSearchTerm] = useState("");
  const [filteredConversions, setFilteredConversions] = useState([]);

  const fetchData = useCallback(async () => {
    setLoading(true);
    const apiUrl = `${domain}/api/UomConversions`;
    try {
      const response = await axios.get(apiUrl, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      setConversionData(response.data);
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("Failed to fetch UOM conversions.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  useEffect(() => {
    const lowercasedSearchTerm = searchTerm.toLowerCase();
    const results = conversionData.filter(
      (conv) =>
        conv.fromUom?.unitName.toLowerCase().includes(lowercasedSearchTerm) ||
        conv.toUom?.unitName.toLowerCase().includes(lowercasedSearchTerm)
    );
    setFilteredConversions(results);
    setCurrentPage(1);
  }, [searchTerm, conversionData]);

  const deleteConversion = async (id) => {
    const apiUrl = `${domain}/api/UomConversions/${id}`;
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this UOM conversion?"
    );

    if (!confirmDelete) {
      return;
    }
    try {
      await axios.delete(apiUrl);
      toast.success("UOM Conversion Successfully Deleted!");
      fetchData();
    } catch (error) {
      console.error("Error deleting conversion:", error);
      toast.error("Failed to delete UOM conversion.");
    }
  };

  const openModal = (conversion = null) => {
    setConversionToEdit(conversion);
    setIsModalVisible(true);
  };

  const closeModal = () => {
    setIsModalVisible(false);
    setConversionToEdit(null);
    fetchData();
  };

  // Pagination Logic
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filteredConversions.slice(
    indexOfFirstItem,
    indexOfLastItem
  );

  const totalPages = Math.ceil(filteredConversions.length / itemsPerPage);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  return (
    <div className="relative w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8 min-h-screen">
      <ToastContainer
        position="top-right"
        autoClose={3000}
        hideProgressBar={false}
        newestOnTop={false}
        closeOnClick
        rtl={false}
        pauseOnFocusLoss
        draggable
        pauseOnHover
      />

      {/* Header Section */}
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-gray-900">UOM Conversions</h2>
        <p className="mt-2 text-md text-gray-600">
          Manage and view all unit of measurement conversion rules in your
          system.
        </p>
      </div>

      {/* Controls Section */}
      <div className="flex flex-col lg:flex-row justify-between items-center mb-6 gap-4">
        <button
          onClick={() => openModal()}
          className="w-full lg:w-auto flex items-center justify-center gap-2 bg-orange-600 text-white font-semibold py-3 px-6 rounded-lg hover:bg-orange-700 transition duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-orange-500"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-5 w-5"
            viewBox="0 0 20 20"
            fill="currentColor"
          >
            <path
              fillRule="evenodd"
              d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-11a1 1 0 10-2 0v2H7a1 1 0 100 2h2v2a1 1 0 102 0v-2h2a1 1 0 100-2h-2V7z"
              clipRule="evenodd"
            />
          </svg>
          Add New Conversion
        </button>

        <div className="w-full lg:w-1/3">
          <input
            type="text"
            placeholder="🔍 Search by Unit Name..."
            className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 focus:border-transparent transition duration-200"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Modal */}
      {isModalVisible && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900 bg-opacity-60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-4xl max-h-[90vh] overflow-y-auto">
            <AddUomConversion
              onClose={closeModal}
              refreshData={fetchData}
              conversionToEdit={conversionToEdit}
            />
          </div>
        </div>
      )}

      {/* Content Section */}
      <div className="bg-white rounded-xl shadow-lg overflow-hidden">
        {loading ? (
          <div className="flex justify-center items-center py-12">
            <Loader />
          </div>
        ) : (
          <>
            {/* Desktop Table View */}
            <div className="hidden md:block overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th
                      scope="col"
                      className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                    >
                      From Unit
                    </th>
                    <th
                      scope="col"
                      className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                    >
                      To Unit
                    </th>
                    <th
                      scope="col"
                      className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                    >
                      Conversion Rate
                    </th>
                    <th
                      scope="col"
                      className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                    >
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {currentItems.length === 0 && !loading ? (
                    <tr>
                      <td
                        colSpan="4"
                        className="px-6 py-8 text-center text-gray-500"
                      >
                        <div className="flex flex-col items-center justify-center">
                          <svg
                            className="w-12 h-12 text-gray-400 mb-4"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                            />
                          </svg>
                          <p className="text-lg font-medium text-gray-600">
                            No UOM conversions found.
                          </p>
                          <p className="text-sm text-gray-500 mt-1">
                            Try adjusting your search or add a new conversion.
                          </p>
                        </div>
                      </td>
                    </tr>
                  ) : (
                    currentItems.map((item) => (
                      <tr
                        key={item.id}
                        className="hover:bg-gray-50 transition-colors duration-150 ease-in-out"
                      >
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          {item.fromUom?.unitName || "N/A"}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          {item.toUom?.unitName || "N/A"}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700">
                          <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-orange-100 text-orange-800">
                            {item.conversionRate}
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                          <div className="flex items-center space-x-3">
                            <button
                              onClick={() => openModal(item)}
                              className="text-indigo-600 hover:text-indigo-900 font-medium transition duration-200"
                            >
                              Edit
                            </button>
                            <button
                              onClick={() => deleteConversion(item.id)}
                              className="text-red-600 hover:text-red-900 font-medium transition duration-200"
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>

            {/* Mobile Card View */}
            <div className="md:hidden space-y-4 p-4">
              {currentItems.length === 0 && !loading ? (
                <div className="text-center py-8 text-gray-500 border-2 border-dashed rounded-lg">
                  <svg
                    className="w-12 h-12 text-gray-400 mx-auto mb-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                    />
                  </svg>
                  <p className="text-lg font-medium text-gray-600">
                    No UOM conversions found.
                  </p>
                  <p className="text-sm text-gray-500 mt-1">
                    Try adjusting your search or add a new conversion.
                  </p>
                </div>
              ) : (
                currentItems.map((item) => (
                  <div
                    key={item.id}
                    className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow duration-200"
                  >
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center space-x-2">
                        <span className="text-sm font-medium text-gray-900">
                          {item.fromUom?.unitName || "N/A"}
                        </span>
                        <span className="text-gray-400">→</span>
                        <span className="text-sm font-medium text-gray-900">
                          {item.toUom?.unitName || "N/A"}
                        </span>
                      </div>
                      <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-orange-100 text-orange-800">
                        Rate: {item.conversionRate}
                      </span>
                    </div>
                    <div className="flex justify-end space-x-3 pt-2 border-t border-gray-100">
                      {/* <button
                        onClick={() => openModal(item)}
                        className="text-indigo-600 hover:text-indigo-900 text-sm font-medium transition duration-200"
                      >
                        Edit
                      </button> */}
                      <button
                        onClick={() => deleteConversion(item.id)}
                        className="text-red-600 hover:text-red-900 text-sm font-medium transition duration-200"
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <nav
          className="flex justify-center items-center space-x-2 mt-8"
          aria-label="Pagination"
        >
          {Array.from({ length: totalPages }).map((_, index) => (
            <button
              key={index}
              onClick={() => paginate(index + 1)}
              className={`min-w-[40px] px-4 py-2 rounded-lg text-sm font-semibold transition duration-300 ease-in-out focus:outline-none focus:ring-2 focus:ring-offset-2 ${
                currentPage === index + 1
                  ? "bg-orange-600 text-white shadow-md focus:ring-orange-500"
                  : "bg-white text-gray-700 border border-gray-300 hover:bg-gray-100 hover:text-gray-900 focus:ring-gray-400"
              }`}
            >
              {index + 1}
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default AllUomConversions;
