import React, { useState, useEffect } from "react";
import { FaTimes } from "react-icons/fa";

const RejectItemModal = ({ isOpen, onClose, onSubmit, lineItem }) => {
  const [quantityToReject, setQuantityToReject] = useState(1);
  const [error, setError] = useState("");

  // Reset state when the modal is opened for a new item
  useEffect(() => {
    if (isOpen) {
      setQuantityToReject(1);
      setError("");
    }
  }, [isOpen]);

  if (!isOpen || !lineItem) return null;

  const maxRejectable = lineItem.remainingQuantity || 0;

  const handleQuantityChange = (e) => {
    const value = e.target.value;
    if (value === "") {
      setQuantityToReject("");
      setError("");
      return;
    }

    const numValue = parseInt(value, 10);
    if (numValue > maxRejectable) {
      setError(
        `Cannot reject more than the remaining quantity (${maxRejectable}).`
      );
    } else if (numValue < 1) {
      setError("Quantity must be at least 1.");
    } else {
      setError("");
    }
    setQuantityToReject(numValue);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (error || !quantityToReject || quantityToReject < 1) {
      // Don't submit if there's an error or invalid input
      return;
    }
    onSubmit(quantityToReject);
  };

  const inputStyles =
    "block w-full p-2 border border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm";

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-50 p-4">
      <div className="relative bg-white rounded-lg shadow-xl w-full max-w-md">
        <div className="flex items-center justify-between p-4 border-b">
          <h3 className="text-lg font-semibold text-gray-800">Reject Item</h3>
          <button
            onClick={onClose}
            className="p-2 text-gray-500 rounded-full hover:bg-gray-200"
          >
            <FaTimes />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="p-6 space-y-4">
            <div>
              <p className="text-sm text-gray-600">Product</p>
              <p className="font-medium text-gray-900">
                {lineItem.productName}
              </p>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-gray-600">Ordered</p>
                <p className="font-medium">{lineItem.orderedQuantity}</p>
              </div>
              <div>
                <p className="text-sm text-gray-600">Remaining</p>
                <p className="font-medium text-green-600">
                  {lineItem.remainingQuantity}
                </p>
              </div>
            </div>

            <div>
              <label
                htmlFor="quantityToReject"
                className="block text-sm font-medium text-gray-700 mb-1"
              >
                Quantity to Reject *
              </label>
              <input
                id="quantityToReject"
                type="number"
                min="1"
                max={maxRejectable}
                value={quantityToReject}
                onChange={handleQuantityChange}
                required
                className={`${inputStyles} ${error ? "border-red-500" : ""}`}
              />
              {error && <p className="text-red-600 text-xs mt-1">{error}</p>}
            </div>
          </div>

          <div className="flex items-center justify-end p-4 border-t bg-gray-50 space-x-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-100 font-medium text-sm"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={!!error || !quantityToReject || quantityToReject < 1}
              className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-medium text-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Confirm Rejection
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default RejectItemModal;
