import React, { useEffect, useState } from "react";
import Loader from "../../../loader/Loader";
import { toast } from "react-toastify";
import axios from "axios";
import { domain } from "../../../../security";

const AddUnitOfMeasurement = ({ onClose, refreshData, unitToEdit }) => {
  const [formData, setFormData] = useState({
    unitName: "",
  });
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (unitToEdit) {
      setFormData({
        unitName: unitToEdit.unitName,
      });
    } else {
      setFormData({
        unitName: "",
      });
    }
  }, [unitToEdit]);

  const handleInputChange = (e) => {
    const { id, value } = e.target;
    setFormData({ ...formData, [id]: value });
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    // API endpoint changed to UnitOfMeasurements
    const apiUrl = domain + "/api/UnitOfMeasurements";

    try {
      if (unitToEdit) {
        // Update logic
        await axios.put(`${apiUrl}/${unitToEdit.id}`, formData, {
          headers: {
            "Content-Type": "application/json",
          },
        });
        toast.success("Unit of Measurement updated successfully");
      } else {
        // Add logic
        await axios.post(apiUrl, formData, {
          headers: {
            "Content-Type": "application/json",
          },
        });
        toast.success("Unit of Measurement added successfully");
      }
      setIsLoading(false);
      refreshData();
      onClose();
    } catch (error) {
      console.error("Error:", error.response?.data || error.message);
      setIsLoading(false);
      toast.error(
        `${unitToEdit ? "Error updating" : "Error adding"} unit: ${
          error.response?.data || error.message
        }`
      );
    }
  };

  return (
    <div>
      {isLoading && <Loader />}
      <div className="relative w-full pt-4 py-4 px-12">
        <button
          onClick={onClose}
          className="absolute top-0 right-0 p-2 text-gray-500 hover:text-gray-700"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-6 w-6"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </button>
        <h2 className="text-3xl mb-4">
          {unitToEdit ? "Edit Unit" : "Add Unit"}
        </h2>
        <p className="mb-4">
          Add or update a Unit of Measurement using this form.
        </p>
        <form onSubmit={handleFormSubmit}>
          <div className="mt-5">
            <span>Unit Name</span>
            <input
              id="unitName" // id must match state property
              type="text"
              placeholder="pcs, kg, box, etc."
              className="border border-gray-400 py-1 px-2 w-full"
              value={formData.unitName}
              onChange={handleInputChange}
              required
            />
          </div>
          <div className="mt-5">
            <button className="w-full bg-orange-600 py-3 text-center text-white">
              {unitToEdit ? "Update Unit" : "Add Unit"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddUnitOfMeasurement;
