// src/components/YourModule/PurchaseOrderModule/AllPurchaseOrders.jsx

import React, { useCallback, useEffect, useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import axios from "axios";
import Loader from "../../../loader/Loader";
import AddPurchaseOrder from "./AddPurchaseOrder";
import Pagination from "../../Pagination";
import RejectItemModal from "./RejectItemModal";
import { domain } from "../../../../security";

const AllPurchaseOrders = () => {
  const [poData, setPoData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [poToEdit, setPoToEdit] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [expandedPO, setExpandedPO] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(5);
  const [activeTab, setActiveTab] = useState("temp");

  const [isRejectModalOpen, setIsRejectModalOpen] = useState(false);
  const [itemToReject, setItemToReject] = useState({
    lineItem: null,
    headerId: null,
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    const apiUrl = `${domain}/api/PurchaseOrderHeaders`;
    try {
      const response = await axios.get(apiUrl);
      const sortedData = response.data.sort((a, b) => b.id - a.id);
      setPoData(sortedData);
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("Failed to fetch purchase orders.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // CHANGE 2: Update the openRejectModal handler to accept both the item and its PO ID
  const openRejectModal = (item, headerId) => {
    setItemToReject({ lineItem: item, headerId: headerId });
    setIsRejectModalOpen(true);
  };

  const closeRejectModal = () => {
    setIsRejectModalOpen(false);
    setItemToReject({ lineItem: null, headerId: null });
  };

  // CHANGE 3: Fix the API call in handleRejectSubmit
  const handleRejectSubmit = async (quantityToReject) => {
    if (!itemToReject.lineItem || !itemToReject.headerId) return;

    setLoading(true);
    try {
      // Construct the correct URL using both headerId and lineItemId
      const apiUrl = `${domain}/api/PurchaseOrderHeaders/${itemToReject.headerId}/lineitems/${itemToReject.lineItem.id}/reject`;

      // Send the request body with the correct property name: "QuantityToReject"
      await axios.post(apiUrl, {
        QuantityToReject: quantityToReject,
      });

      toast.success(
        `${quantityToReject} unit(s) of ${itemToReject.lineItem.productName} rejected successfully!`
      );
      closeRejectModal();
      fetchData(); // Refresh data to show updated quantities
    } catch (error) {
      toast.error(error.response?.data?.message || "Failed to reject item.");
    } finally {
      setLoading(false);
    }
  };

  // --- Other Functions (Unchanged) ---

  const finalizePurchaseOrder = async (id) => {
    if (
      !window.confirm(
        "Are you sure you want to finalize this Purchase Order? This action cannot be undone."
      )
    ) {
      return;
    }
    setLoading(true);
    try {
      await axios.post(`${domain}/api/PurchaseOrderHeaders/${id}/finalize`);
      toast.success("Purchase Order finalized successfully!");
      fetchData();
    } catch (error) {
      toast.error(
        error.response?.data?.message || "Failed to finalize Purchase Order."
      );
    } finally {
      setLoading(false);
    }
  };

  const checkForGoodsReceipts = async (poId) => {
    try {
      const response = await axios.get(`${domain}/api/GoodsReceipts`);
      return response.data.some((gr) => gr.purchaseOrderHeaderId === poId);
    } catch (error) {
      console.error("Error checking goods receipts:", error);
      return false;
    }
  };

  const deletePurchaseOrder = async (id) => {
    const hasGoodsReceipts = await checkForGoodsReceipts(id);
    if (hasGoodsReceipts) {
      toast.error(
        "Cannot delete purchase order with existing goods receipts. Please cancel instead."
      );
      return;
    }

    if (
      !window.confirm("Are you sure you want to delete this purchase order?")
    ) {
      return;
    }

    try {
      await axios.delete(`${domain}/api/PurchaseOrderHeaders/${id}`);
      toast.success("Purchase Order Deleted!");
      if (expandedPO === id) {
        setExpandedPO(null);
      }
      fetchData();
    } catch (error) {
      console.error("Error deleting PO:", error);
      toast.error(
        error.response?.data?.message || "Failed to delete purchase order."
      );
    }
  };

  // --- UI and Filtering Logic (Unchanged) ---

  const tabFilteredPOs = poData.filter((po) =>
    activeTab === "temp"
      ? po.poNumber?.startsWith("TMP-")
      : !po.poNumber?.startsWith("TMP-")
  );

  const filteredPOs = tabFilteredPOs.filter(
    (po) =>
      po.poNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      po.vendor.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentPOs = filteredPOs.slice(indexOfFirstItem, indexOfLastItem);

  const openModal = (po = null) => {
    setPoToEdit(po);
    setIsModalVisible(true);
  };
  const closeModal = () => {
    setIsModalVisible(false);
    setPoToEdit(null);
  };
  const toggleExpandPO = (poId) =>
    setExpandedPO(expandedPO === poId ? null : poId);
  const paginate = (pageNumber) => setCurrentPage(pageNumber);
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setCurrentPage(1);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "Closed":
        return "bg-green-100 text-green-800 border-green-200";
      case "Pending":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      default:
        return "bg-gray-100 text-gray-800 border-gray-200";
    }
  };

  return (
    <div className="min-h-screen py-6">
      <div className="max-w-6xl mx-auto px-4">
        <ToastContainer position="top-right" autoClose={3000} />

        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">
              Purchase Orders
            </h1>
            <p className="text-gray-600 text-sm">
              {filteredPOs.length} order(s) found
            </p>
          </div>
          <button
            onClick={() => openModal()}
            className="bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium py-2 px-4 rounded-lg transition"
          >
            + New PO
          </button>
        </div>

        <div className="mb-4 border-b border-gray-200">
          <nav className="-mb-px flex space-x-8" aria-label="Tabs">
            <button
              onClick={() => handleTabChange("temp")}
              className={`whitespace-nowrap py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === "temp"
                  ? "border-blue-500 text-blue-600"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
              }`}
            >
              Temporary POs
            </button>
            <button
              onClick={() => handleTabChange("po")}
              className={`whitespace-nowrap py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === "po"
                  ? "border-blue-500 text-blue-600"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
              }`}
            >
              Finalized POs
            </button>
          </nav>
        </div>

        <div className="mb-6">
          <input
            type="text"
            placeholder="Search PO or vendor..."
            className="w-full p-3 border border-gray-300 rounded-lg text-sm"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setCurrentPage(1);
            }}
          />
        </div>

        {isModalVisible && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-4xl max-h-[90vh] overflow-hidden">
              <AddPurchaseOrder
                onClose={closeModal}
                refreshData={fetchData}
                poToEdit={poToEdit}
              />
            </div>
          </div>
        )}

        {/* Pass the correct lineItem object to the modal */}
        <RejectItemModal
          isOpen={isRejectModalOpen}
          onClose={closeRejectModal}
          onSubmit={handleRejectSubmit}
          lineItem={itemToReject.lineItem}
        />

        {loading ? (
          <div className="flex justify-center items-center h-32">
            <Loader />
          </div>
        ) : (
          <>
            <div className="space-y-3 mb-6">
              {currentPOs.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  No purchase orders found
                </div>
              ) : (
                currentPOs.map((po) => (
                  <div
                    key={po.id}
                    className="bg-white rounded-lg border border-gray-200 overflow-hidden"
                  >
                    <div
                      className="p-4 hover:bg-gray-50 cursor-pointer transition"
                      onClick={() => toggleExpandPO(po.id)}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-4">
                          <div
                            className={`transform transition-transform ${
                              expandedPO === po.id ? "rotate-90" : ""
                            }`}
                          >
                            <span className="text-gray-400">▶</span>
                          </div>
                          <div className="bg-blue-50 p-2 rounded">
                            <span className="text-blue-600 text-sm font-medium">
                              📋
                            </span>
                          </div>
                          <div>
                            <h3 className="font-semibold text-gray-900">
                              {po.poNumber}
                            </h3>
                            <p className="text-sm text-gray-600">{po.vendor}</p>
                          </div>
                        </div>
                        <div className="flex items-center space-x-3">
                          <span
                            className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(
                              po.status
                            )}`}
                          >
                            {po.status}
                          </span>
                          <span className="text-lg font-semibold text-gray-900">
                            {new Intl.NumberFormat("en-US", {
                              style: "currency",
                              currency: po.currency || "USD",
                            }).format(po.grandTotal)}
                          </span>
                        </div>
                      </div>
                      <div className="flex items-center justify-between text-sm text-gray-600 mt-2">
                        <div className="flex space-x-4">
                          <span>{po.location}</span>
                          <span>
                            {new Date(po.creationDate).toLocaleDateString()}
                          </span>
                          <span>{po.purchaseOrderLineItems.length} items</span>
                        </div>
                        <div className="flex space-x-2">
                          {po.poNumber?.startsWith("TMP-") && (
                            <>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  finalizePurchaseOrder(po.id);
                                }}
                                className="text-green-600 hover:text-green-800 text-sm font-medium px-2 py-1 rounded hover:bg-green-50"
                              >
                                Finalize PO
                              </button>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  openModal(po);
                                }}
                                className="text-blue-600 hover:text-blue-800 text-sm font-medium px-2 py-1 rounded hover:bg-blue-50"
                              >
                                Edit
                              </button>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  deletePurchaseOrder(po.id);
                                }}
                                className="text-red-600 hover:text-red-800 text-sm font-medium px-2 py-1 rounded hover:bg-red-50"
                              >
                                Delete
                              </button>
                            </>
                          )}
                        </div>
                      </div>
                    </div>

                    {expandedPO === po.id && (
                      <div className="border-t border-gray-200 bg-gray-50 p-4">
                        <h4 className="font-semibold text-gray-900 mb-3 text-sm">
                          Line Items ({po.purchaseOrderLineItems.length})
                        </h4>
                        <div className="space-y-2">
                          {po.purchaseOrderLineItems.map((item) => (
                            <div
                              key={item.id}
                              className="flex justify-between items-center p-3 bg-white rounded border text-sm"
                            >
                              <div className="flex-1">
                                <p className="font-medium text-gray-900">
                                  {item.lineNumber}.
                                  {item.productName || "No Product Name"}
                                </p>
                                <div className="text-gray-600 text-xs mt-1 flex flex-wrap gap-x-3 gap-y-1">
                                  <span>
                                    Ordered:{" "}
                                    <strong>{item.orderedQuantity}</strong>{" "}
                                    {item.unitOfMeasure}
                                  </span>
                                  <span className="text-green-600">
                                    Received:{" "}
                                    <strong>
                                      {item.receivedQuantity || 0}
                                    </strong>
                                  </span>
                                  <span className="text-red-600">
                                    Rejected:{" "}
                                    <strong>
                                      {item.rejectedQuantity || 0}
                                    </strong>
                                  </span>
                                  <span className="font-medium text-gray-800">
                                    Remaining:{" "}
                                    <strong>
                                      {item.remainingQuantity || 0}
                                    </strong>
                                  </span>
                                </div>
                                <p className="text-gray-500 text-xs mt-1">
                                  {item.glAccount && `GL: ${item.glAccount}`}
                                  {item.glAccount && item.costCenter && " • "}
                                  {item.costCenter &&
                                    `Cost Center: ${item.costCenter}`}
                                </p>
                              </div>

                              <div className="text-right flex flex-col items-end ml-4">
                                <p className="font-semibold text-gray-900">
                                  {new Intl.NumberFormat("en-US", {
                                    style: "currency",
                                    currency: po.currency || "USD",
                                  }).format(item.lineTotal)}
                                </p>
                                <p className="text-xs text-gray-500 mt-1">
                                  @
                                  {new Intl.NumberFormat("en-US", {
                                    style: "currency",
                                    currency: po.currency || "USD",
                                  }).format(item.unitPrice)}
                                  /unit
                                </p>
                                {/* CHANGE 4: Pass the PO ID (po.id) to the openRejectModal function */}
                                {activeTab === "po" &&
                                  item.remainingQuantity > 0 && (
                                    <button
                                      onClick={(e) => {
                                        e.stopPropagation();
                                        // Pass both the item and its parent PO's ID
                                        openRejectModal(item, po.id);
                                      }}
                                      className="mt-2 text-xs font-medium text-red-600 hover:text-red-800 px-2 py-1 rounded hover:bg-red-50 transition-colors"
                                    >
                                      Rejected
                                    </button>
                                  )}
                              </div>
                            </div>
                          ))}

                          {po.shippingCost > 0 && (
                            <div className="flex justify-between items-center p-3 bg-white rounded border text-sm">
                              <p className="font-medium text-gray-900">
                                Shipping Cost
                              </p>
                              <p className="font-semibold text-gray-900">
                                {new Intl.NumberFormat("en-US", {
                                  style: "currency",
                                  currency: po.currency || "USD",
                                }).format(po.shippingCost)}
                              </p>
                            </div>
                          )}

                          <div className="flex justify-between items-center p-3 bg-blue-50 rounded border border-blue-200 text-sm">
                            <p className="font-bold text-gray-900">
                              Grand Total
                            </p>
                            <p className="font-bold text-blue-700">
                              {new Intl.NumberFormat("en-US", {
                                style: "currency",
                                currency: po.currency || "USD",
                              }).format(po.grandTotal)}
                            </p>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            {filteredPOs.length > itemsPerPage && (
              <Pagination
                itemsPerPage={itemsPerPage}
                totalItems={filteredPOs.length}
                currentPage={currentPage}
                paginate={paginate}
              />
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default AllPurchaseOrders;
