// src/components/YourModule/PurchaseOrderModule/AddPurchaseOrder.js

import React, { useEffect, useState, useCallback } from "react";
import Loader from "../../../loader/Loader";
import { toast } from "react-toastify";
import axios from "axios";
import { domain } from "../../../../security";
import CreatableSelect from "react-select/creatable";
import { FaTrash, FaTimes, FaPlus, FaFileInvoiceDollar } from "react-icons/fa";

// --- FINAL: Updated initial state for line items to match new backend model ---
const initialLineItem = {
  lineNumber: 1,
  productId: null,
  productName: "",
  quantity: 1,
  unitOfMeasureId: "", // Use ID for the UOM
  unitPrice: 0,
  lineTotal: 0,
  rejectedQuantity: 0, // New field, defaults to 0
  isCustom: false,
  // remainingQuantity is calculated for display and not part of the initial state
};

// --- AddItemModal component remains the same ---
const AddItemModal = ({ isOpen, onClose, onSelectOption }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg p-6 w-80 max-w-sm">
        <h3 className="text-lg font-medium text-gray-900 mb-4">
          Add Item Type
        </h3>
        <p className="text-sm text-gray-600 mb-6">
          How would you like to add this item?
        </p>
        <div className="flex flex-col space-y-3">
          <button
            onClick={() => onSelectOption("system")}
            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium"
          >
            Item in System
          </button>
          <button
            onClick={() => onSelectOption("new")}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium"
          >
            New Custom Item
          </button>
        </div>
        <button
          onClick={onClose}
          className="mt-4 px-4 py-2 text-gray-600 hover:text-gray-800 font-medium w-full"
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

const AddPurchaseOrder = ({ onClose, refreshData, poToEdit }) => {
  const [formData, setFormData] = useState({
    poNumber: "",
    creationDate: new Date().toISOString().split("T")[0],
    expectedDeliveryDate: "",
    status: "Open",
    internalNotes: "",
    locationId: "",
    vendorId: "",
    shippingCost: 0,
    currency: "PHP",
    paymentTerms: "Net 30",
    grandTotal: 0,
    purchaseOrderLineItems: [],
  });

  const [locations, setLocations] = useState([]);
  const [vendors, setVendors] = useState([]);
  const [unitOfMeasures, setUnitOfMeasures] = useState([]);
  const [pricelistOptions, setPricelistOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPricelistLoading, setIsPricelistLoading] = useState(false);
  const [isAddItemModalOpen, setIsAddItemModalOpen] = useState(false);

  const inputStyles =
    "block w-full p-2 border border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm";
  const labelStyles = "block text-sm font-medium text-gray-700 mb-1";
  const readOnlyInputStyles = `${inputStyles} bg-gray-100 cursor-not-allowed`;

  // --- FINAL: Fetch initial data, including UOMs ---
  useEffect(() => {
    const fetchInitialData = async () => {
      setIsLoading(true);
      try {
        if (!poToEdit) {
          try {
            const nextPONumberRes = await axios.get(
              `${domain}/api/PurchaseOrderHeaders/next-tmp-number`
            );
            // Robustly handle different possible API response shapes
            let nextPoNumber = nextPONumberRes.data;
            if (typeof nextPoNumber === "object" && nextPoNumber !== null) {
              nextPoNumber =
                nextPoNumber.nextPoNumber ||
                nextPoNumber.poNumber ||
                JSON.stringify(nextPoNumber);
            }
            if (nextPoNumber) {
              setFormData((prev) => ({
                ...prev,
                poNumber: nextPoNumber.toString(),
              }));
            }
          } catch (error) {
            console.error("Error fetching next PO number:", error);
            toast.warning(
              "Could not generate PO number. Please enter manually."
            );
          }
        }

        const [locationsRes, vendorsRes, uomRes] = await Promise.all([
          axios.get(`${domain}/api/locations`),
          axios.get(`${domain}/api/vendors`),
          axios.get(`${domain}/api/UnitOfMeasurements`),
        ]);
        setLocations(locationsRes.data);
        setVendors(vendorsRes.data);
        setUnitOfMeasures(uomRes.data);
      } catch (error) {
        toast.error("Failed to load form data.");
        console.error("Error fetching initial data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchInitialData();
  }, [poToEdit]);

  // --- FINAL: Populate form for editing, ensuring new fields have defaults ---
  useEffect(() => {
    if (poToEdit) {
      setFormData({
        ...poToEdit,
        creationDate: poToEdit.creationDate.split("T")[0],
        expectedDeliveryDate:
          poToEdit.expectedDeliveryDate?.split("T")[0] || "",
        purchaseOrderLineItems: poToEdit.purchaseOrderLineItems.map((item) => ({
          ...item,
          rejectedQuantity: item.rejectedQuantity || 0,
          remainingQuantity: item.remainingQuantity || 0, // Comes from API
        })),
      });
    }
  }, [poToEdit]);

  useEffect(() => {
    if (!formData.locationId) {
      setPricelistOptions([]);
      return;
    }
    const fetchPricelist = async () => {
      setIsPricelistLoading(true);
      try {
        const response = await axios.get(`${domain}/api/Pricelists`);
        const selectedLocationId = parseInt(formData.locationId, 10);
        const filteredPricelist = response.data.filter(
          (item) => item.locationId === selectedLocationId
        );
        const formattedOptions = filteredPricelist.map((item) => ({
          value: item.id,
          label: `${item.product} - ${item.itemCode}`,
          unitPrice: item.unitPrice || 0,
          unitOfMeasureId: item.purchaseUom?.id, // Get UOM ID from pricelist
        }));
        setPricelistOptions(formattedOptions);
      } catch (error) {
        toast.error(`Failed to load products for the selected location.`);
        setPricelistOptions([]);
      } finally {
        setIsPricelistLoading(false);
      }
    };

    fetchPricelist();
  }, [formData.locationId]);

  const handleHeaderChange = (e) => {
    const { id, value } = e.target;
    setFormData({ ...formData, [id]: value });
  };

  const calculateTotals = useCallback((items, shippingCost) => {
    const subtotal = items.reduce(
      (acc, item) => acc + (item.quantity || 0) * (item.unitPrice || 0),
      0
    );
    const grandTotal = subtotal + (parseFloat(shippingCost) || 0);
    return { subtotal, grandTotal };
  }, []);

  useEffect(() => {
    const { grandTotal } = calculateTotals(
      formData.purchaseOrderLineItems,
      formData.shippingCost
    );
    setFormData((prev) => ({ ...prev, grandTotal }));
  }, [formData.purchaseOrderLineItems, formData.shippingCost, calculateTotals]);

  const handleLineItemChange = (index, field, value) => {
    const updatedItems = [...formData.purchaseOrderLineItems];
    const lineItem = updatedItems[index];
    lineItem[field] = value;

    if (field === "quantity" || field === "unitPrice") {
      lineItem.lineTotal = (lineItem.quantity || 0) * (lineItem.unitPrice || 0);
    }
    setFormData((prev) => ({ ...prev, purchaseOrderLineItems: updatedItems }));
  };

  // --- FINAL: Handle product selection, setting UOM automatically ---
  const handleProductSelect = (index, selectedOption) => {
    const updatedItems = [...formData.purchaseOrderLineItems];
    const lineItem = updatedItems[index];

    if (selectedOption) {
      lineItem.productId = selectedOption.value;
      lineItem.productName = selectedOption.label;
      lineItem.unitPrice = selectedOption.unitPrice || 0;
      lineItem.unitOfMeasureId = selectedOption.unitOfMeasureId || ""; // Set UOM from product
    } else {
      lineItem.productId = null;
      lineItem.productName = "";
      lineItem.unitPrice = 0;
      lineItem.unitOfMeasureId = "";
    }
    lineItem.lineTotal = (lineItem.quantity || 0) * (lineItem.unitPrice || 0);
    setFormData((prev) => ({ ...prev, purchaseOrderLineItems: updatedItems }));
  };

  const handleCustomProductChange = (index, value) => {
    const updatedItems = [...formData.purchaseOrderLineItems];
    const lineItem = updatedItems[index];
    lineItem.productName = value;
    setFormData((prev) => ({ ...prev, purchaseOrderLineItems: updatedItems }));
  };

  const openAddItemModal = () => setIsAddItemModalOpen(true);

  const handleAddItemChoice = (choice) => {
    setIsAddItemModalOpen(false);
    const newLineItem = {
      ...initialLineItem,
      lineNumber: formData.purchaseOrderLineItems.length + 1,
      isCustom: choice === "new",
    };
    setFormData((prev) => ({
      ...prev,
      purchaseOrderLineItems: [...prev.purchaseOrderLineItems, newLineItem],
    }));
  };

  const addLineItem = () => openAddItemModal();

  const removeLineItem = (index) => {
    setFormData((prev) => ({
      ...prev,
      purchaseOrderLineItems: prev.purchaseOrderLineItems.filter(
        (_, i) => i !== index
      ),
    }));
  };

  // --- FINAL: Submit a clean DTO matching the backend model ---
  const handleFormSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    const submissionData = {
      ...formData,
      purchaseOrderLineItems: formData.purchaseOrderLineItems.map((item) => ({
        id: item.id || 0,
        lineNumber: item.lineNumber,
        productId: item.productId,
        productName: item.productName,
        quantity: item.quantity ? parseInt(item.quantity, 10) : 0,
        unitOfMeasureId: item.unitOfMeasureId
          ? parseInt(item.unitOfMeasureId, 10)
          : null,
        unitPrice: item.unitPrice ? parseFloat(item.unitPrice) : 0,
        lineTotal: item.lineTotal,
        rejectedQuantity: item.rejectedQuantity || 0,
        itemStatus: item.itemStatus || false,
      })),
    };

    submissionData.locationId = parseInt(submissionData.locationId, 10);
    submissionData.vendorId = parseInt(submissionData.vendorId, 10);
    submissionData.shippingCost = parseFloat(submissionData.shippingCost);

    try {
      if (poToEdit) {
        await axios.put(
          `${domain}/api/PurchaseOrderHeaders/${poToEdit.id}`,
          submissionData
        );
        toast.success("Purchase Order updated successfully");
      } else {
        await axios.post(`${domain}/api/PurchaseOrderHeaders`, submissionData);
        toast.success("Purchase Order created successfully");
      }
      refreshData();
      onClose();
    } catch (error) {
      console.error(
        "Error submitting PO:",
        error.response?.data || error.message
      );
      toast.error(
        `Error: ${
          error.response?.data?.message || "An unexpected error occurred."
        }`
      );
    } finally {
      setIsLoading(false);
    }
  };

  const subtotal = calculateTotals(formData.purchaseOrderLineItems, 0).subtotal;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
      <AddItemModal
        isOpen={isAddItemModalOpen}
        onClose={() => setIsAddItemModalOpen(false)}
        onSelectOption={handleAddItemChoice}
      />
      <div className="relative flex h-full max-h-[95vh] w-full max-w-7xl flex-col rounded-lg bg-gray-100 shadow-xl">
        <div className="flex flex-shrink-0 items-center justify-between rounded-t-lg border-b bg-white p-4">
          <div className="flex items-center space-x-3">
            <FaFileInvoiceDollar className="h-7 w-7 text-indigo-600" />
            <h2 className="text-xl font-semibold text-gray-800">
              {poToEdit ? "Edit Purchase Order" : "Create Purchase Order"}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-gray-500 rounded-full hover:bg-gray-200"
          >
            <FaTimes className="h-5 w-5" />
          </button>
        </div>

        {isLoading && <Loader />}

        <form
          onSubmit={handleFormSubmit}
          className="flex-grow overflow-y-auto p-6 space-y-6"
        >
          {/* PO Header Details */}
          <div className="rounded-lg border bg-white p-6">
            <h3 className="text-lg font-medium leading-6 text-gray-900 mb-4">
              PO Details
            </h3>
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
              <div>
                <label htmlFor="poNumber" className={labelStyles}>
                  PO Number *
                </label>
                <input
                  id="poNumber"
                  type="text"
                  value={formData.poNumber}
                  onChange={handleHeaderChange}
                  required
                  className={`${inputStyles} bg-gray-100 text-gray-600 cursor-not-allowed`}
                  readOnly
                />
                {!poToEdit && (
                  <p className="text-xs text-gray-500 mt-1">
                    Temporary number, finalized after creation.
                  </p>
                )}
              </div>
              <div>
                <label htmlFor="locationId" className={labelStyles}>
                  Location *
                </label>
                <select
                  id="locationId"
                  value={formData.locationId}
                  onChange={handleHeaderChange}
                  required
                  className={inputStyles}
                >
                  <option value="">Select Location</option>
                  {locations.map((loc) => (
                    <option key={loc.id} value={loc.id}>
                      {loc.locationName}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label htmlFor="vendorId" className={labelStyles}>
                  Vendor *
                </label>
                <select
                  id="vendorId"
                  value={formData.vendorId}
                  onChange={handleHeaderChange}
                  required
                  className={inputStyles}
                >
                  <option value="">Select Vendor</option>
                  {vendors.map((v) => (
                    <option key={v.id} value={v.id}>
                      {v.vendorName}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label htmlFor="creationDate" className={labelStyles}>
                  Creation Date *
                </label>
                <input
                  id="creationDate"
                  type="date"
                  value={formData.creationDate}
                  onChange={handleHeaderChange}
                  required
                  className={inputStyles}
                />
              </div>
              <div>
                <label htmlFor="expectedDeliveryDate" className={labelStyles}>
                  Expected Delivery *
                </label>
                <input
                  id="expectedDeliveryDate"
                  type="date"
                  value={formData.expectedDeliveryDate}
                  onChange={handleHeaderChange}
                  className={inputStyles}
                  required
                />
              </div>
              <div>
                <label htmlFor="status" className={labelStyles}>
                  Status
                </label>
                <select
                  id="status"
                  value={formData.status}
                  onChange={handleHeaderChange}
                  className={inputStyles}
                >
                  <option value="Open">Open</option>
                  <option value="Closed">Closed</option>
                  <option value="Cancelled">Cancelled</option>
                </select>
              </div>
            </div>
          </div>

          {/* Line Items Section */}
          <div className="rounded-lg border bg-white">
            <div className="flex items-center justify-between p-6 border-b">
              <h3 className="text-lg font-medium leading-6 text-gray-900">
                Line Items
              </h3>
              <button
                type="button"
                onClick={addLineItem}
                className="flex items-center space-x-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors text-sm font-medium"
              >
                <FaPlus />
                <span>Add Item</span>
              </button>
            </div>
            <div className="overflow-x-auto">
              <table className="min-w-full">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-1/4 min-w-[250px]">
                      Product / Description
                    </th>
                    <th className="px-3 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-20">
                      Qty
                    </th>
                    <th className="px-3 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-24">
                      UOM
                    </th>
                    <th className="px-3 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-28">
                      Unit Price
                    </th>
                    <th className="px-3 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-28">
                      Remaining Qty
                    </th>
                    <th className="px-3 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-28">
                      Rejected Qty
                    </th>
                    <th className="px-3 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-28">
                      Total
                    </th>
                    <th className="px-3 py-3 text-center text-xs font-semibold text-gray-600 uppercase tracking-wider w-12">
                      Action
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {formData.purchaseOrderLineItems.length === 0 ? (
                    <tr>
                      <td
                        colSpan="8"
                        className="px-6 py-8 text-center text-gray-500"
                      >
                        No items added yet. Click "Add Item" to get started.
                      </td>
                    </tr>
                  ) : (
                    formData.purchaseOrderLineItems.map((item, index) => (
                      <tr key={index}>
                        <td className="px-3 py-4">
                          {item.isCustom ? (
                            <input
                              type="text"
                              value={item.productName}
                              onChange={(e) =>
                                handleCustomProductChange(index, e.target.value)
                              }
                              placeholder="Enter custom item name..."
                              className={`${inputStyles} w-full min-w-[200px]`}
                            />
                          ) : (
                            <CreatableSelect
                              isClearable
                              isDisabled={!formData.locationId}
                              isLoading={isPricelistLoading}
                              options={pricelistOptions}
                              placeholder={
                                formData.locationId
                                  ? "Select a product..."
                                  : "Select a location first"
                              }
                              value={
                                pricelistOptions.find(
                                  (opt) => opt.value === item.productId
                                ) || null
                              }
                              onChange={(option) =>
                                handleProductSelect(index, option)
                              }
                              menuPortalTarget={document.body}
                              styles={{
                                menuPortal: (base) => ({
                                  ...base,
                                  zIndex: 9999,
                                }),
                                control: (base) => ({
                                  ...base,
                                  minWidth: "200px",
                                }),
                              }}
                            />
                          )}
                        </td>
                        <td className="px-3 py-4">
                          <input
                            type="number"
                            min="1"
                            value={item.quantity}
                            onChange={(e) =>
                              handleLineItemChange(
                                index,
                                "quantity",
                                e.target.value
                              )
                            }
                            className={`${inputStyles} w-20`}
                          />
                        </td>
                        <td className="px-3 py-4">
                          <select
                            value={item.unitOfMeasureId || ""}
                            onChange={(e) =>
                              handleLineItemChange(
                                index,
                                "unitOfMeasureId",
                                e.target.value
                              )
                            }
                            className={`${inputStyles} w-24`}
                          >
                            <option value="">Select</option>
                            {unitOfMeasures.map((uom) => (
                              <option key={uom.id} value={uom.id}>
                                {uom.unitName}
                              </option>
                            ))}
                          </select>
                        </td>
                        <td className="px-3 py-4">
                          <input
                            type="number"
                            step="0.01"
                            min="0"
                            value={item.unitPrice}
                            onChange={(e) =>
                              handleLineItemChange(
                                index,
                                "unitPrice",
                                e.target.value
                              )
                            }
                            className={`${inputStyles} w-28`}
                          />
                        </td>
                        <td className="px-3 py-4">
                          <input
                            type="number"
                            value={
                              poToEdit ? item.remainingQuantity : item.quantity
                            }
                            className={readOnlyInputStyles}
                            readOnly
                          />
                        </td>
                        <td className="px-3 py-4">
                          <input
                            type="number"
                            value={item.rejectedQuantity || 0}
                            className={readOnlyInputStyles}
                            readOnly
                          />
                        </td>
                        <td className="px-3 py-4 font-medium text-gray-800 whitespace-nowrap">
                          {formData.currency} {item.lineTotal.toFixed(2)}
                        </td>
                        <td className="px-3 py-4 text-center">
                          <button
                            type="button"
                            onClick={() => removeLineItem(index)}
                            className="p-2 text-red-500 hover:text-red-700 rounded-full hover:bg-red-50"
                            title="Remove item"
                          >
                            <FaTrash />
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            <div className="space-y-4">
              <div className="rounded-lg border bg-white p-6">
                <label htmlFor="internalNotes" className={labelStyles}>
                  Internal Notes
                </label>
                <textarea
                  id="internalNotes"
                  value={formData.internalNotes}
                  onChange={handleHeaderChange}
                  rows="4"
                  className={`${inputStyles} resize-none`}
                />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="rounded-lg border bg-white p-6">
                  <label htmlFor="paymentTerms" className={labelStyles}>
                    Payment Terms
                  </label>
                  <select
                    id="paymentTerms"
                    value={formData.paymentTerms}
                    onChange={handleHeaderChange}
                    className={inputStyles}
                  >
                    <option>Net 30</option>
                    <option>Net 15</option>
                    <option>Net 60</option>
                    <option>Due on Receipt</option>
                  </select>
                </div>
                <div className="rounded-lg border bg-white p-6">
                  <label htmlFor="currency" className={labelStyles}>
                    Currency
                  </label>
                  <select
                    id="currency"
                    value={formData.currency}
                    onChange={handleHeaderChange}
                    className={inputStyles}
                  >
                    <option>PHP</option>
                    <option>USD</option>
                    <option>EUR</option>
                  </select>
                </div>
              </div>
            </div>
            <div className="rounded-lg border bg-white p-6 flex flex-col justify-between">
              <div className="space-y-3">
                <div className="flex justify-between items-center text-md">
                  <span className="text-gray-600">Subtotal:</span>
                  <span className="font-semibold text-gray-800">
                    {formData.currency} {subtotal.toFixed(2)}
                  </span>
                </div>
                <div className="flex justify-between items-center text-md">
                  <span className="text-gray-600">Shipping Cost:</span>
                  <div className="flex items-center">
                    <span className="text-gray-500 mr-2">
                      {formData.currency}
                    </span>
                    <input
                      type="number"
                      step="0.01"
                      id="shippingCost"
                      value={formData.shippingCost}
                      onChange={handleHeaderChange}
                      className={`${inputStyles} w-32`}
                    />
                  </div>
                </div>
              </div>
              <div className="border-t mt-4 pt-4">
                <div className="flex justify-between items-center text-xl font-bold text-gray-900">
                  <span>Grand Total:</span>
                  <span>
                    {formData.currency} {formData.grandTotal.toFixed(2)}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </form>

        <div className="flex flex-shrink-0 items-center justify-end space-x-4 rounded-b-lg border-t bg-gray-50 p-4">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-100 font-medium"
          >
            Cancel
          </button>
          <button
            type="submit"
            onClick={handleFormSubmit}
            className="px-5 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium flex items-center space-x-2 disabled:opacity-50"
            disabled={isLoading}
          >
            {isLoading && (
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
            )}
            <span>
              {isLoading ? "Saving..." : poToEdit ? "Update PO" : "Create PO"}
            </span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddPurchaseOrder;
