import React, { useEffect, useState } from "react";
import Loader from "../../../loader/Loader";
import { toast } from "react-toastify";
import axios from "axios";
import { domain } from "../../../../security";

const AddVendor = ({ onClose, refreshData, vendorToEdit }) => {
  const [formData, setFormData] = useState({
    vendorName: "",
    contactPerson: "",
    email: "",
    phoneNumber: "",
    address: "",
    specialization: "",
    vendorStatus: "Active", // Default value
  });
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (vendorToEdit) {
      // If editing, populate form with existing data
      setFormData({
        vendorName: vendorToEdit.vendorName || "",
        contactPerson: vendorToEdit.contactPerson || "",
        email: vendorToEdit.email || "",
        phoneNumber: vendorToEdit.phoneNumber || "",
        address: vendorToEdit.address || "",
        specialization: vendorToEdit.specialization || "",
        vendorStatus: vendorToEdit.vendorStatus || "Active",
      });
    } else {
      // If adding, reset form
      setFormData({
        vendorName: "",
        contactPerson: "",
        email: "",
        phoneNumber: "",
        address: "",
        specialization: "",
        vendorStatus: "Active",
      });
    }
  }, [vendorToEdit]);

  const handleInputChange = (e) => {
    const { id, value } = e.target;
    setFormData({ ...formData, [id]: value });
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    const apiUrl = `${domain}/api/Vendors`;

    try {
      if (vendorToEdit) {
        // Update logic (PUT request)
        await axios.put(`${apiUrl}/${vendorToEdit.id}`, formData);
        toast.success("Vendor updated successfully");
      } else {
        // Add new logic (POST request)
        await axios.post(apiUrl, formData);
        toast.success("Vendor added successfully");
      }
      setIsLoading(false);
      refreshData();
      onClose();
    } catch (error) {
      console.error("Error:", error.response?.data || error.message);
      setIsLoading(false);
      toast.error(
        `${vendorToEdit ? "Error updating" : "Error adding"} vendor.`
      );
    }
  };

  return (
    <div>
      {isLoading && <Loader />}
      <div className="relative w-full pt-4 py-4 px-8">
        <button
          onClick={onClose}
          className="absolute top-2 right-2 p-2 text-gray-500 hover:text-gray-700"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-6 w-6"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </button>

        <h2 className="text-2xl font-bold mb-4">
          {vendorToEdit ? "Edit Vendor" : "Add New Vendor"}
        </h2>

        <form onSubmit={handleFormSubmit} className="space-y-4">
          <div>
            <label
              htmlFor="vendorName"
              className="block text-sm font-medium text-gray-700"
            >
              Vendor Name
            </label>
            <input
              id="vendorName"
              type="text"
              placeholder="e.g., Global Tech Suppliers"
              required
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.vendorName}
              onChange={handleInputChange}
            />
          </div>
          <div>
            <label
              htmlFor="contactPerson"
              className="block text-sm font-medium text-gray-700"
            >
              Contact Person
            </label>
            <input
              id="contactPerson"
              type="text"
              placeholder="e.g., Jane Doe"
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.contactPerson}
              onChange={handleInputChange}
            />
          </div>
          <div>
            <label
              htmlFor="email"
              className="block text-sm font-medium text-gray-700"
            >
              Email
            </label>
            <input
              id="email"
              type="email"
              placeholder="e.g., contact@gts.com"
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.email}
              onChange={handleInputChange}
            />
          </div>
          <div>
            <label
              htmlFor="phoneNumber"
              className="block text-sm font-medium text-gray-700"
            >
              Phone Number
            </label>
            <input
              id="phoneNumber"
              type="tel"
              placeholder="e.g., (555) 123-4567"
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.phoneNumber}
              onChange={handleInputChange}
            />
          </div>
          <div>
            <label
              htmlFor="address"
              className="block text-sm font-medium text-gray-700"
            >
              Address
            </label>
            <textarea
              id="address"
              placeholder="e.g., 123 Tech Way, Silicon Valley, CA"
              rows="3"
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.address}
              onChange={handleInputChange}
            ></textarea>
          </div>
          <div>
            <label
              htmlFor="specialization"
              className="block text-sm font-medium text-gray-700"
            >
              Specialization
            </label>
            <input
              id="specialization"
              type="text"
              placeholder="e.g., CPUs & GPUs"
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.specialization}
              onChange={handleInputChange}
            />
          </div>
          <div>
            <label
              htmlFor="vendorStatus"
              className="block text-sm font-medium text-gray-700"
            >
              Status
            </label>
            <select
              id="vendorStatus"
              className="mt-1 border border-gray-300 py-2 px-3 w-full rounded-md"
              value={formData.vendorStatus}
              onChange={handleInputChange}
            >
              <option value="Active">Active</option>
              <option value="Inactive">Inactive</option>
            </select>
          </div>

          <div className="mt-6">
            <button
              type="submit"
              className="w-full bg-orange-600 py-3 text-center text-white rounded-lg hover:bg-orange-700 transition duration-300"
            >
              {vendorToEdit ? "Update Vendor" : "Add Vendor"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddVendor;
